def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    by_id={}
    for s in spans:
        by_id[s.get('id')]=s
    observed=set()
    for a in inputs.get('semantic_answers',[]):
        if isinstance(a,dict) and a.get('id') is not None:
            observed.add(a.get('id'))
    corrections=[]
    for q in inputs.get('queries',[]):
        qid=q.get('id')
        if qid not in observed:
            continue
        ids=q.get('unit_ids',[])
        if not ids:
            continue
        focus_span=by_id.get(ids[len(ids)-1])
        if focus_span is None:
            continue
        focus=focus_span.get('text','')
        if not isinstance(focus,str):
            focus=str(focus)
        ft=focus.casefold()
        window=[]
        evidence=[]
        for uid in ids:
            s=by_id.get(uid)
            if s is None:
                continue
            x=s.get('text','')
            if not isinstance(x,str):
                x=str(x)
            window.append(x)
            evidence.append({'unit_id':uid,'quote':x})
        wt=' '.join(window).casefold()
        passive_return=('shall be returned' in ft and 'confidential information' in ft and ('all copies' in ft or 'including all copies' in ft))
        substitute=('in lieu of return' in ft and 'destroyed' in ft and 'certif' in ft)
        retention_followup=(('in such an instance' in ft or 'retention period required by law' in ft) and 'return or destroy' in ft and 'retained confidential information' in ft)
        survival=(('obligation' in ft or 'undertaking' in ft) and ('continue to apply' in ft or 'continue to be bound' in ft) and ('retained confidential information' in ft or 'return of documents' in ft))
        op=q.get('operation')
        choice=None
        if op=='disposal_retention_clause_role':
            if passive_return or substitute:
                choice='operative_disposal'
            elif retention_followup:
                choice='supplemental_linked_effect'
            elif survival:
                choice='no_relevant_operative_effect'
        elif passive_return:
            if op=='principal_disposal_action':
                choice='return_to_information_supplier'
            elif op=='principal_disposal_trigger' and 'termination of this agreement' in wt:
                choice='agreement_termination'
            elif op=='principal_disposal_information_scope':
                choice='confidential_information_and_all_copies'
            elif op=='disposal_retention_actor_role' and 'and its representatives' in ft:
                choice='holder_and_its_representatives'
            elif op=='disposal_retention_qualification' and 'unless otherwise instructed in writing' in wt:
                choice='different_written_instructions_exception'
            elif op=='disposal_temporal_qualification':
                choice='no_additional_timing'
        elif substitute:
            if op=='principal_disposal_action':
                choice='destroy_in_lieu_with_certification'
            elif op=='principal_disposal_trigger' and 'termination of this agreement' in wt:
                choice='agreement_termination'
            elif op=='principal_disposal_information_scope' and 'including all copies' in wt:
                choice='confidential_information_and_all_copies'
            elif op=='disposal_retention_qualification' and 'unless otherwise instructed in writing' in wt:
                choice='different_written_instructions_exception'
            elif op=='disposal_temporal_qualification':
                choice='no_additional_timing'
        if choice is None:
            continue
        old=None
        for a in inputs.get('semantic_answers',[]):
            if isinstance(a,dict) and a.get('id')==qid:
                old=a.get('choice')
                break
        if old!=choice:
            corrections.append({'id':qid,'choice':choice,'evidence':evidence})
    return {'corrections':corrections}

