def _sr_window_ids(spans,i):
    ids=[]
    raw=_sr_text(spans[i])
    t=raw.casefold().strip()
    if i>0 and (re.search(r'\bforegoing\b',raw,re.I) is not None or _sr_heading(_sr_text(spans[i-1]))):
        ids.append(spans[i-1].get('id'))
    linked_retention=t.startswith('in such an instance') or ('retention period required by law' in t and 'retained' in t)
    if linked_retention:
        j=i-1
        stop=i-6
        while j>=0 and j>=stop:
            p=_sr_text(spans[j]).casefold()
            if 'may retain' in p and ('applicable law' in p or 'required by law' in p):
                x=spans[j].get('id')
                if x not in ids:
                    ids.append(x)
                break
            j-=1
    elif _sr_linked(raw):
        j=i-1
        stop=i-6
        while j>=0 and j>=stop:
            if _sr_principal(_sr_text(spans[j])):
                if j>0 and _sr_heading(_sr_text(spans[j-1])):
                    x=spans[j-1].get('id')
                    if x not in ids:
                        ids.append(x)
                x=spans[j].get('id')
                if x not in ids:
                    ids.append(x)
                break
            j-=1
    x=spans[i].get('id')
    if x not in ids:
        ids.append(x)
    return ids

def _sr_add(out,term,ids):
    support=[]
    for x in ids:
        if x is not None and x not in support:
            support.append(x)
    def contains(x,wanted):
        todo=[x]
        while todo:
            y=todo.pop()
            if y==wanted:
                return True
            if isinstance(y,list):
                for z in y[1:]:
                    if isinstance(z,list):
                        todo.append(z)
        return False
    def exceptions(x):
        if x==['no_exceptions']:
            return []
        if isinstance(x,list) and x:
            if x[0]=='exception_set' and len(x)>1:
                return [x[1]]
            if x[0]=='add_exception' and len(x)>2:
                return exceptions(x[1])+[x[2]]
        return []
    def make_exceptions(xs):
        clean=[]
        for x in xs:
            if x not in clean:
                clean.append(x)
        if not clean:
            return ['no_exceptions']
        v=['exception_set',clean[0]]
        for x in clean[1:]:
            v=['add_exception',v,x]
        return v
    def branch(action,wanted):
        return isinstance(action,list) and len(action)==3 and action[0]=='action_alternative' and (action[1]==wanted or action[2]==wanted)
    if isinstance(term,list) and len(term)==5 and term[0]=='retention_permission':
        rex=['retention_exception',term[1],term[2],term[4]]
        for s in out:
            old=s.get('term')
            old_ids=s.get('support_ids',[])
            overlap=False
            for x in support:
                if x in old_ids:
                    overlap=True
                    break
            if overlap and isinstance(old,list) and len(old)==5 and old[0]=='disposal_obligation' and not contains(old[4],rex):
                old[4]=make_exceptions(exceptions(old[4])+[rex])
    if isinstance(term,list) and len(term)==5 and term[0]=='disposal_obligation':
        for s in out:
            old=s.get('term')
            if not (isinstance(old,list) and len(old)==5 and old[0]=='disposal_obligation'):
                continue
            if old[1]!=term[1] or old[3]!=term[3]:
                continue
            merged=None
            if branch(term[2],old[2]):
                merged=term[2]
            elif branch(old[2],term[2]):
                merged=old[2]
            if merged is None:
                continue
            old[2]=merged
            old[4]=make_exceptions(exceptions(old[4])+exceptions(term[4]))
            for x in support:
                if x not in s.get('support_ids',[]):
                    s.setdefault('support_ids',[]).append(x)
            return
    for s in out:
        if s.get('term')==term:
            for x in support:
                if x not in s.get('support_ids',[]):
                    s.setdefault('support_ids',[]).append(x)
            return
    out.append({'term':term,'support_ids':support})
